let lang = "en";
const listeners = new Set();

export function t(key, vars) {
  let s = STRINGS[lang][key] ?? STRINGS.en[key] ?? key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.split(`{${k}}`).join(String(v));
  return s;
}
export const getLang = () => lang;
export function onLangChange(fn) { listeners.add(fn); return () => listeners.delete(fn); }

export function setLang(next) {
  lang = STRINGS[next] ? next : "en";
  document.documentElement.lang = lang;
  document.querySelectorAll("[data-i18n]").forEach((el) => { el.textContent = t(el.dataset.i18n); });
  document.querySelectorAll("[data-i18n-ph]").forEach((el) => { el.setAttribute("placeholder", t(el.dataset.i18nPh)); });
  document.querySelectorAll("[data-i18n-alt]").forEach((el) => { el.setAttribute("alt", t(el.dataset.i18nAlt)); });
  document.querySelectorAll("[data-i18n-aria]").forEach((el) => { el.setAttribute("aria-label", t(el.dataset.i18nAria)); });
  document.querySelectorAll(".lang button").forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.lang === lang)));
  document.title = t("meta_title");
  document.querySelector('meta[name="description"]')?.setAttribute("content", t("meta_desc"));
  try { localStorage.setItem("allurus-lang", lang); } catch (e) { /* storage blocked: language just isn't remembered */ }
  listeners.forEach((fn) => fn(lang));
}

export function initialLang() {
  let saved = "";
  try { saved = localStorage.getItem("allurus-lang") || ""; } catch (e) { /* ignore */ }
  if (STRINGS[saved]) return saved;
  return (navigator.language || "").toLowerCase().startsWith("ms") ? "ms" : "en";
}
